function generateLeagueInfoData(n,t){t.preventDefault();$.ajax({type:"GET",url:urlPrefix()+`/League/DumpLeagueInfo?leagueId=${n}`,success:function(n){$("#leagueDataRaw").val(JSON.stringify(n,null,"\t"));$("#leagueRequestContent").text("");jsonView.format(n,"#leagueRequestContent");$("#leagueInfoRequest").modal()},error:function(t){console.log("failed"+JSON.stringify(t)+urlPrefix()+`/League/DumpLeagueInfo?leagueId=${n}`)}})}function updateLeagueInfoData(n){n.preventDefault();var t=JSON.parse($("#leagueDataRaw").val());console.log(t);$.ajax({type:"POST",url:urlPrefix()+"/League/UpdateLeagueInfo",contentType:"application/json; charset=utf-8",dataType:"json",data:JSON.stringify(t),success:function(){console.log("success")},error:function(){console.log("failed")}})}function getRootUrl(){return window.location.origin?window.location.origin+"/":window.location.protocol+"/"+window.location.host+"/"}function urlPrefix(){return getRootUrl()+$("#urlPrefix").val()}